import{_ as s,o as t,c as n,a2 as r}from"./chunks/framework.oPQd_6mD.js";const m=JSON.parse('{"title":"Sécurité et déploiement","description":"","frontmatter":{},"headers":[],"relativePath":"guide/securite.md","filePath":"guide/securite.md","lastUpdated":null}'),a={name:"guide/securite.md"};function i(o,e,d,c,u,p){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="securite-et-deploiement" tabindex="-1">Sécurité et déploiement <a class="header-anchor" href="#securite-et-deploiement" aria-label="Permalink to &quot;Sécurité et déploiement&quot;">​</a></h1><p>Les applications créées sont des <strong>laboratoires locaux</strong>, pas des services prêts pour Internet. Ne publiez pas les ports 3030 et 3031 directement.</p><p>Avant une mise en production, mettez en place une authentification Feathers côté serveur, des autorisations par service/méthode, un stockage persistant, le chiffrement HTTPS et un proxy avec contrôles d&#39;origine. Ne vous reposez pas uniquement sur le masquage de l&#39;interface.</p><p>Pour le SSG, publiez seulement des pages publiques. Ne sauvegardez jamais de jetons, de données personnelles ni de configuration <code>.env</code> dans les artefacts HTML.</p><p>Les builds frontaux n&#39;ont pas besoin d&#39;accéder aux secrets de l&#39;API. Les connexions SQL, LDAP ou à d&#39;autres services doivent être gérées dans le processus Feathers, pas dans Vite.</p><p>Le CLI refuse de modifier un dossier existant et rejette les liens symboliques présents dans la destination. Utilisez les contrôles de version et examinez les fichiers créés avant une mise en service.</p>',6)])])}const _=s(a,[["render",i]]);export{m as __pageData,_ as default};
